def from_dict(cls, d: dict) -> FlawClassRecord:
    # EVERY field off disk is untrusted, not only the two `load` checks.
    # A bare `d["flaw_class"]` raises KeyError — outside the
    # MemoryIntegrityError family `load` documents — and returns whatever
    # type the file happened to carry, so a JSON `"1"` becomes a record
    # invisible to every caller, all of which use `int`.
    # `experiments_seen` was validated on no path at all, and
    # `record_experiment` then executes `rec.experiments_seen += 1` on it.
    if "flaw_class" not in d:
        raise MemoryIntegrityError(f"record carries no flaw_class: {d!r}")
    try:
        flaw_class = int(d["flaw_class"])
    except (TypeError, ValueError) as exc:
        raise MemoryIntegrityError(
            f"flaw_class is not an integer ({d['flaw_class']!r})") from exc
    seen = _check_count(d.get("experiments_seen", 0), "experiments_seen")
